const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.request_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_REQUEST_ID', message: 'request_id is required.' } }];
}

return [{ json: { decision: 'VALID', request_id: body.request_id } }];

const validated = $('Validate Input').first().json;

const approvalRaw = $('Fetch Approval Log').first().json;
const approvalRow = Array.isArray(approvalRaw) ? approvalRaw[0] : approvalRaw;

const mergeRaw = $('Fetch Merge Request').first().json;
const mergeRow = Array.isArray(mergeRaw) ? mergeRaw[0] : mergeRaw;

if (!approvalRow || approvalRow.approval_status !== 'approved' || !approvalRow.staged_payload_json) {
  return [{ json: {
    decision: 'REJECTED', reason: 'NOT_APPROVED', request_id: validated.request_id,
    message: 'No approved, staged payload found for this request_id.'
  }}];
}

if (!mergeRow) {
  return [{ json: {
    decision: 'REJECTED', reason: 'MERGE_REQUEST_NOT_FOUND', request_id: validated.request_id,
    message: 'No merge_requests row found for this request_id.'
  }}];
}

// This path is only for existing-parent merges - it patches each child
// independently, which only makes sense when the parent already exists.
// A brand-new parent and its children need to come into existence
// together as one operation, which this deliberately cannot do -
// wf30 (the Feeds pipeline) is still the only path for that mode.
if (mergeRow.is_new_parent) {
  return [{ json: {
    decision: 'REJECTED', reason: 'WRONG_MODE', request_id: validated.request_id,
    message: 'This is a new-parent merge - the direct API path only supports existing-parent merges. Use wf30 instead.'
  }}];
}

return [{ json: {
  decision: 'READY',
  request_id: validated.request_id,
  seller_id: mergeRow.seller_id,
  marketplace_id: mergeRow.marketplace_id,
  messages: approvalRow.staged_payload_json.messages || []
}}];

const ready = $('Check Ready To Submit').first().json;
const upstream = $input.first().json;
const rows = Array.isArray(upstream) ? upstream : (upstream && upstream.request_id ? [upstream] : []);

if (rows.length === 0) {
  return [{ json: {
    decision: 'REJECTED', reason: 'CLAIM_LOST', request_id: ready.request_id,
    message: 'Could not claim this submission - another request may have already claimed it between the ready-check and now. Refusing rather than risk a duplicate.'
  }}];
}

return [{ json: {
  decision: 'CLAIMED',
  request_id: ready.request_id,
  seller_id: ready.seller_id,
  marketplace_id: ready.marketplace_id,
  messages: ready.messages
}}];

const claimed = $('Check Claim Succeeded').first().json;
const sellingPartnerRaw = $('Get Seller Selling Partner ID').first().json;
const sellingPartnerRow = Array.isArray(sellingPartnerRaw) ? sellingPartnerRaw[0] : sellingPartnerRaw;
const sellingPartnerId = sellingPartnerRow && sellingPartnerRow.selling_partner_id;
const accessToken = $('Exchange for Access Token').first().json.access_token;

if (!sellingPartnerId || !accessToken) {
  return [{ json: {
    decision: 'REJECTED', reason: 'MISSING_CREDENTIALS', request_id: claimed.request_id,
    message: 'Could not resolve a selling_partner_id or access_token before submitting - refusing to attempt any real calls without both.'
  }}];
}

const results = [];

// A verify call that throws isn't necessarily a real failure - a 404
// right after patching a listing can just be Amazon's own catalog/search
// index not having caught up yet, the same kind of delay this retry
// schedule already exists to wait out (see the comment on verifyDelaysMs
// below). Only a genuinely non-retryable status should permanently drop
// an entry from the retry rotation.
function isRetryableStatus(err) {
  let status = null;
  if (err && err.response && typeof err.response.status === 'number') status = err.response.status;
  else if (err && err.response && typeof err.response.statusCode === 'number') status = err.response.statusCode;
  else if (err && typeof err.statusCode === 'number') status = err.statusCode;
  else {
    // Last resort: axios's own default error message embeds the code -
    // e.g. "Request failed with status code 404".
    const match = /status code (\d{3})/i.exec((err && err.message) || '');
    if (match) status = parseInt(match[1], 10);
  }
  if (status === 404) return true;
  if (status >= 500 && status < 600) return true;
  if (!status) return true; // network error / timeout / no response at all - worth another try
  return false;
}

// Phase 1: patch every child first, without verifying yet. Separated
// from verification on purpose - see phase 2's comment for why.
for (const msg of claimed.messages) {
  const entry = { sku: msg.sku, patch_status: null, patch_issues: [], verified_child: false, verify_issues: [], verify_attempts: 0, error: null };

  try {
    const patchResponse = await this.helpers.httpRequest({
      method: 'PATCH',
      url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId + '/' + encodeURIComponent(msg.sku),
      qs: { marketplaceIds: claimed.marketplace_id, issueLocale: 'en_US' },
      headers: { 'Content-Type': 'application/json', 'x-amz-access-token': accessToken },
      body: { productType: msg.productType, patches: msg.patches },
      json: true
    });
    entry.patch_status = patchResponse.status || null;
    entry.patch_issues = patchResponse.issues || [];
  } catch (err) {
    entry.error = 'patch call failed: ' + (err.message || String(err));
  }

  results.push(entry);
}

// Phase 2: verify every child, with a shared wait-and-retry schedule -
// found necessary from a real run today, not a hypothetical: a genuine
// merge showed verified_child=false on the very first check right after
// patching, then true a few minutes later once Amazon's own downstream
// processing had actually caught up. One immediate check isn't
// reliable. Waiting together, once per round, rather than each child
// running its own full retry sequence independently, keeps the total
// added time roughly constant regardless of how many children there are.
// Stops early the moment everything's confirmed or every remaining
// entry has hit a real error - no point waiting out the full schedule
// once there's nothing left to check.
// Matches wf34's verify_and_attach window, not its own shorter
// create window - lengthened from the original ~40s after a real
// request (BLU-M into Parent_SR12) used the full old budget without
// confirming, on a parent this same codebase's own comments already
// document as having needed longer than a short window elsewhere.
const verifyDelaysMs = [5000, 10000, 15000, 20000, 30000]; // ~80s max total extra wait, shared
for (let attempt = 0; attempt <= verifyDelaysMs.length; attempt++) {
  if (attempt > 0) {
    await new Promise(function(resolve) { setTimeout(resolve, verifyDelaysMs[attempt - 1]); });
  }

  const stillPending = results.filter(function(r) { return !r.verified_child && !r.error; });
  if (stillPending.length === 0) break;

  for (const entry of stillPending) {
    entry.verify_attempts++;
    try {
      const stateResponse = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId + '/' + encodeURIComponent(entry.sku),
        qs: { marketplaceIds: claimed.marketplace_id, includedData: 'attributes,issues' },
        headers: { 'x-amz-access-token': accessToken },
        json: true
      });
      const attrs = stateResponse.attributes || {};
      entry.verified_child = !!(attrs.parentage_level && attrs.parentage_level.some(function(e) { return e.value === 'child'; }));
      entry.verify_issues = stateResponse.issues || [];
    } catch (err) {
      const message = 'verify call failed: ' + (err.message || String(err));
      // stillPending's own filter above only excludes entries with
      // entry.error set - recording a retryable failure here instead
      // keeps this entry in the rotation for the remaining rounds,
      // rather than silently dropping it after one bad response.
      if (isRetryableStatus(err)) {
        entry.last_verify_error = message;
      } else {
        entry.error = message;
      }
    }
  }
}

return [{ json: {
  decision: 'SUBMITTED',
  request_id: claimed.request_id,
  results: results
}}];

const submitted = $input.first().json;
const results = submitted.results || [];

const allVerified = results.length > 0 && results.every(function(r) { return r.verified_child; });
const noneVerified = results.every(function(r) { return !r.verified_child; });

// Matches dashboard.jsx's existing status vocabulary on purpose - the
// same words this app already shows for the Feeds pipeline's outcome,
// so the user sees consistent language regardless of which mechanism
// actually ran underneath.
const finalStatus = allVerified ? 'verified' : (noneVerified ? 'failed' : 'partially_failed');

return [{ json: {
  decision: 'SUMMARIZED',
  request_id: submitted.request_id,
  final_status: finalStatus,
  child_count: results.length,
  verified_count: results.filter(function(r) { return r.verified_child; }).length,
  results: results
}}];
